import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_findWrapPos_TriageGen0Test {

    private HelpFormatter formatter;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
    }

    @Test
    public void testFindWrapPosWithNewLine() {
        assertEquals(4, formatter.findWrapPos("Hello\nWorld", 10, 0));
    }

    @Test
    public void testFindWrapPosWithTab() {
        assertEquals(5, formatter.findWrapPos("Hello\tWorld", 10, 0));
    }

    @Test
    public void testFindWrapPosWithSpace() {
        assertEquals(5, formatter.findWrapPos("Hello World", 10, 0));
    }

    @Test
    public void testFindWrapPosNoWrap() {
        assertEquals(10, formatter.findWrapPos("HelloWorld", 10, 0));
    }

    @Test
    public void testFindWrapPosAtEnd() {
        assertEquals(-1, formatter.findWrapPos("HelloWorld", 10, 5));
    }

    @Test
    public void testFindWrapPosNoWhitespace() {
        assertEquals(10, formatter.findWrapPos("HelloWorld!", 10, 0));
    }

    @Test
    public void testFindWrapPosNoWrapAndNoWhitespace() {
        assertEquals(10, formatter.findWrapPos("HelloWorld!", 10, 0));
    }

    @Test
    public void testFindWrapPosStartAfterLineEnd() {
        assertEquals(-1, formatter.findWrapPos("Hello\nWorld", 10, 6));
    }

    @Test
    public void testFindWrapPosStartAfterTab() {
        assertEquals(6, formatter.findWrapPos("Hello\tWorld", 10, 5));
    }

    @Test
    public void testFindWrapPosExactWidth() {
        assertEquals(10, formatter.findWrapPos("ExactWidth", 10, 0));
    }

    @Test
    public void testFindWrapPosBeyondWidth() {
        assertEquals(10, formatter.findWrapPos("BeyondWidth", 5, 0));
    }

    @Test
    public void testFindWrapPosMultipleSpaces() {
        assertEquals(5, formatter.findWrapPos("Hello   World", 10, 0));
    }

    @Test
    public void testFindWrapPosMultipleNewLines() {
        assertEquals(4, formatter.findWrapPos("Line1\nLine2\nLine3", 10, 0));
    }
}
